//! The v4 backup container against desktop-written files (`backup-container-v4.json`, generated by
//! `oracle/backup-v4.mjs` from the real desktop writer), and `open_any` over both versions.
mod common;
use cl_crypto::backup_container::{ContainerError, KeyMaterial};
use cl_crypto::backup_v4::{open_any, open_v4, Opened, WriterV4, HEADER_LEN_V4};
use cl_crypto::encoding::from_b64;
use common::{s, vectors};
use serde_json::Value;

#[test]
fn reads_desktop_v4_generations() {
    let v = vectors("backup-container-v4.json");
    let pw = s(&v, "password");
    let mut km: Option<KeyMaterial> = None;
    for g in ["gen1", "gen2"] {
        let file = from_b64(s(&v[g], "container_b64")).unwrap();
        let opened = open_v4(&file, pw, km.as_ref()).unwrap();
        let want: Value = v[g]["index"].clone();
        assert_eq!(serde_json::to_value(&opened.index).unwrap(), want, "{g}");
        assert_eq!(opened.dead_bytes, v[g]["deadBytes"].as_u64().unwrap(), "{g} dead bytes");
        for r in &opened.index.records {
            opened.read_bytes(&file, &r.id).unwrap_or_else(|e| panic!("{g} {}: {e}", r.id));
        }
        km = Some(opened.key_material.clone());
    }
    // gen 2 carried three records at their gen-1 offsets, and they still decrypt (AAD binds gen 1).
    let file = from_b64(s(&v["gen2"], "container_b64")).unwrap();
    let o = open_any(&file, pw, None).unwrap();
    assert!(matches!(o, Opened::V4(_)));
    let carried = o.records().len();
    assert_eq!(carried, 4);
    let meta: Value = serde_json::from_slice(&o.read_bytes(&file, "meta").unwrap()).unwrap();
    assert_eq!(meta, v["meta"]);
}

#[test]
fn desktop_v4_failures_are_clean() {
    let v = vectors("backup-container-v4.json");
    let file = from_b64(s(&v["gen1"], "container_b64")).unwrap();
    assert_eq!(open_v4(&file, "nope", None).err(), Some(ContainerError::AuthFailed));
    // Keyless rollback attempt: zero the newer commit slot of gen 2 -> falls back exactly one generation, still valid.
    let mut f2 = from_b64(s(&v["gen2"], "container_b64")).unwrap();
    let o = open_v4(&f2, s(&v, "password"), None).unwrap();
    assert_eq!(o.index.generation, 2);
    f2[24..24 + 44].fill(0); // slot 0 = even generation 2
    let back = open_v4(&f2, s(&v, "password"), None).unwrap();
    assert_eq!(back.index.generation, 1);
    // A flipped byte in a record: the index opens, the record read fails authentication.
    let mut bad = file.clone();
    let first = back.index.records[0].offset as usize;
    bad[first + 20] ^= 1;
    let ob = open_v4(&bad, s(&v, "password"), None).unwrap();
    assert_eq!(ob.read_bytes(&bad, &ob.index.records[0].id).err(), Some(ContainerError::AuthFailed));
    // Truncated file.
    let mut t = file.clone();
    t.truncate(file.len() - 1);
    assert!(matches!(open_v4(&t, s(&v, "password"), None), Err(ContainerError::Format(_))));
}

#[test]
fn v4_round_trip_in_place_and_crash_leaves_previous_valid() {
    let mut file = Vec::new();
    let km = KeyMaterial::fresh("pw");
    let mut w = WriterV4::create(&mut file, km).unwrap();
    w.add_bytes("meta", b"{\"a\":1}", None).unwrap();
    w.add_bytes("dm:c:2026-10", b"[1]", None).unwrap();
    w.finish("u", "fp1", "2026-11-14T00:00:00.000Z").unwrap();
    let g1 = open_v4(&file, "pw", None).unwrap();
    assert_eq!(g1.index.generation, 1);

    // A run that dies after appending but before the commit: the file still opens as generation 1.
    let before = file.clone();
    {
        let mut w = WriterV4::resume(&mut file, &g1);
        w.add_bytes("meta", b"{\"a\":2}", None).unwrap();
        // dropped: no finish
    }
    assert!(file.len() > before.len());
    let still = open_v4(&file, "pw", None).unwrap();
    assert_eq!(still.index.generation, 1);
    assert_eq!(&*still.read_bytes(&file, "meta").unwrap(), b"{\"a\":1}");

    // The real second generation, on the same file.
    let mut w = WriterV4::resume(&mut file, &still);
    assert_eq!(w.previous_hash("dm:c:2026-10"), Some(cl_crypto::backup_container::sha256_hex(b"[1]").as_str()));
    w.add_bytes("meta", b"{\"a\":3}", None).unwrap();
    w.carry("dm:c:2026-10").unwrap();
    w.finish("u", "fp2", "2026-11-14T01:00:00.000Z").unwrap();
    let g2 = open_v4(&file, "pw", None).unwrap();
    assert_eq!(g2.index.generation, 2);
    assert_eq!(&*g2.read_bytes(&file, "meta").unwrap(), b"{\"a\":3}");
    assert_eq!(&*g2.read_bytes(&file, "dm:c:2026-10").unwrap(), b"[1]");
    assert!(file.len() as u64 > HEADER_LEN_V4);
}

#[test]
fn open_any_reads_v3_and_rejects_others() {
    let v = vectors("backup-container-v3.json");
    let file = from_b64(s(&v["generation_1_fresh_write"], "container_b64")).unwrap();
    let o = open_any(&file, s(&v, "password"), None).unwrap();
    assert_eq!(o.version(), 3);
    for r in o.records() {
        o.read_bytes(&file, &r.id).unwrap();
    }
    assert!(matches!(open_any(&b"not a backup at all"[..], "x", None), Err(ContainerError::Format(_))));
}
